// Target: local SillyTavern 1.19.0 / Tavern Helper 4.11.3. Complete single-character generations, including rerolls.
(() => {
  const st = SillyTavern;
  const context = () => typeof st.getContext === 'function' ? st.getContext() : SillyTavern;
  const toolError = message => new (window.parent?.Error ?? Error)(message);
  const name = 'transam_content';
  if (st.ToolManager.tools.some(tool => tool.toFunctionOpenAI().function.name === name)) throw toolError('TRANS-AM content tool is already registered');
  let generation = null;
  const enabled = id => { const prompts = getPreset('in_use').prompts; return (prompts.find(p => (p.id ?? p.identifier) === id) ?? prompts.find(p => (p.id ?? p.identifier) === id.replace(/^ta-/, 'tw-')))?.enabled === true; };
  const normalizeStoryNewlines = text => {
    if (!/<(?:(?:ta|tw)_(?:plan|zh|time)|bbs_start)\b[^>]*>/i.test(text)) return text;
    // Normalize tagged prose, but leave code, quoted escape examples and file paths untouched.
    const protectedParts = /(<(?:script|style|pre|code|iframe|UpdateVariable|JSONPatch)\b[^>]*>[\s\S]*?(?:<\/(?:script|style|pre|code|iframe|UpdateVariable|JSONPatch)\s*>|$)|```[\s\S]*?(?:```|$)|`[^`\r\n]*(?:`|$)|[A-Za-z]:\\[^\s<>"'`]+|\\\\[A-Za-z0-9_.-]+\\[^\s<>"'`]+|["'](?:\\[rn])+["'])/gi;
    return text.split(protectedParts).map((part, index) => {
      if (index % 2) return part;
      return part.replace(/\\\\|\\r\\n|\\n|\\r/g, token => token === '\\\\' ? token : '\n');
    }).join('');
  };
  const decodeContent = (value, encoding, unicodeEnabled) => {
    if (encoding == null || encoding === 'text') return value;
    if (encoding !== 'unicode-escape' || !unicodeEnabled) throw toolError('Unexpected content encoding');
    // Exactly one explicitly declared payload layer; escaped backslashes stay literal.
    let result = '';
    const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', '"': '"', '/': '/', '\\': '\\' };
    for (let i = 0; i < value.length; i++) {
      if (value[i] !== '\\') { result += value[i]; continue; }
      const next = value[++i];
      if (next === 'u') {
        const hex = value.slice(i + 1, i + 5);
        if (!/^[0-9a-f]{4}$/i.test(hex)) throw toolError('Incomplete Unicode payload escape');
        result += String.fromCharCode(parseInt(hex, 16));
        i += 4;
      } else if (Object.hasOwn(escapes, next)) result += escapes[next];
      else throw toolError('Invalid payload escape');
    }
    return result;
  };
  const decodePrefix = value => {
    let text = '';
    let i = 0;
    for (; i < value.length;) {
      let width = 1;
      let unit = value[i];
      if (unit === '\\') {
        const token = value.slice(i).match(/^\\(?:u[0-9a-f]{4}|["\\/bfnrt])/i)?.[0];
        if (!token) break;
        unit = JSON.parse('"' + token + '"');
        width = token.length;
      }
      text += unit;
      i += width;
    }
    // A received high surrogate without its low surrogate is not a complete character.
    if (/[\uD800-\uDBFF]$/.test(text)) text = text.slice(0, -1);
    return { text, complete: i === value.length };
  };
  const recoverEnvelope = source => {
    let i = 0;
    const values = Object.create(null);
    const whitespace = () => { while (/\s/.test(source[i] ?? '') && i < source.length) i++; };
    const readString = () => {
      if (source[i++] !== '"') return null;
      const start = i;
      while (i < source.length) {
        if (source[i] === '\\') { i += 2; continue; }
        if (source[i] === '"') {
          const decoded = decodePrefix(source.slice(start, i));
          i++;
          return { text: decoded.text, complete: decoded.complete };
        }
        i++;
      }
      const decoded = decodePrefix(source.slice(start));
      return { text: decoded.text, complete: false };
    };
    whitespace();
    if (source[i++] !== '{') return null;
    while (i < source.length) {
      whitespace();
      const key = readString();
      if (!key?.complete || !['transam_unicode', 'content_encoding', 'content'].includes(key.text) || Object.hasOwn(values, key.text)) break;
      whitespace();
      if (source[i++] !== ':') break;
      whitespace();
      if (key.text === 'transam_unicode') {
        if (!/^1(?=\s*[,}]|\s*$)/.test(source.slice(i))) break;
        values.transam_unicode = 1;
        i++;
      } else {
        const value = readString();
        if (!value) break;
        values[key.text] = value.text;
        if (!value.complete) break;
      }
      whitespace();
      if (source[i++] !== ',') break;
    }
    if (values.transam_unicode !== 1 || typeof values.content !== 'string') return null;
    if (values.content_encoding != null && !['text', 'unicode-escape'].includes(values.content_encoding)) return null;
    const content = values.content_encoding === 'unicode-escape' ? decodePrefix(values.content).text : values.content;
    return content.trim() ? content : null;
  };
// Parse only a whole-message, explicitly named textual transport call. Never execute it.
const recoverTextToolCall = source => {
  const raw = source.trim();
  const prefix = /^调用[：:]\s*`(?:default_api:)?transam_content`\s*[（(]参数[：:]\s*`/u.exec(raw);
  if (!prefix) return null;
  const body = raw.slice(prefix[0].length);
  const full = /^(\{[\s\S]*\})`[）)]\s*(?:零部件返回值[：:]\s*limit reached \/ end of turn\.?)?$/u.exec(body);
  if (full) {
    try {
      const args = JSON.parse(full[1]);
      if (typeof args.content !== 'string' || !args.content.trim() || Object.keys(args).some(key => !['content','content_encoding'].includes(key)) || (args.content_encoding != null && args.content_encoding !== 'text')) return null;
      return { content: args.content, partial: false };
    } catch { /* A truncated JSON string can still contain a safely decoded prefix. */ }
  }
  // Partial recovery is deliberately limited to a first, string-valued content field.
  const opening = /^\{\s*"content"\s*:\s*"/u.exec(body);
  if (!opening) return null;
  const text = body.slice(opening[0].length);
  let content = '';
  for (let i = 0; i < text.length;) {
    const char = text[i];
    // A closed content string with an invalid suffix is ambiguous: leave it alone.
    if (char === '"') return null;
    if (char.charCodeAt(0) < 32) break;
    if (char !== '\\') { content += char; i++; continue; }
    const token = /^\\(?:u[0-9a-fA-F]{4}|["\\/bfnrt])/.exec(text.slice(i))?.[0];
    if (!token) break;
    content += JSON.parse('"' + token + '"');
    i += token.length;
  }
  if (/[\uD800-\uDBFF]$/.test(content)) content = content.slice(0,-1);
  // Do not publish an unfinished variable-update payload as executable card data.
  const update = /<UpdateVariable\b/i.exec(content);
  if (update && !/<\/UpdateVariable\s*>/i.test(content.slice(update.index))) content = content.slice(0,update.index);
  return content.trim() ? { content, partial: true } : null;
};

  const restoreEnvelope = async (renderedId, renderedType, allowPartial = false) => {
    const current = generation;
    if (!current || !current.layout || current.attempted || current.restoring || current.chat !== context().chat || current.chatId !== st.getCurrentChatId()) return;
    const targetId = context().chat.length - 1;
    if (targetId < current.minimumIndex || (Number.isInteger(renderedId) && renderedId !== targetId) || !current.prefix.every((message, index) => context().chat[index] === message)) return;
    const last = context().chat.at(-1);
    if (!last || last.is_user || last.is_system || typeof last.mes !== 'string') return;
    // A reroll may keep the floor count unchanged. Do not consume its old page at an early UI-end event.
    const finalRerollRender = renderedType === 'swipe' || renderedType === 'regenerate';
    if (current.reroll && !finalRerollRender && last === current.previousMessage && last.mes === current.previousText && last.swipe_id === current.previousSwipe) return;
    // Accept one optional JSON code fence; never decode arbitrary prose twice.
    const raw = last.mes.trim().replace(/^\uFEFF/, '');
    const wrapped = current.tool ? recoverTextToolCall(raw) : null;
    if (wrapped && (!wrapped.partial || allowPartial)) {
      current.restoring = true;
      try {
        await setChatMessages([{ message_id: current.chat.length - 1, message: wrapped.content,
          extra: { ...last.extra, transam_tool_text_recovery: { status: wrapped.partial ? 'partial' : 'complete', source: last.mes } } }]);
        if (wrapped.partial) toastr.warning('已部分恢复收到的正文，未补写缺失内容；未闭合MVU更新保留在原文备份中。', 'TRANS-AM 输出');
        current.published = true;
      } catch (error) {
        toastr.error('调用文本回写失败，未自动重试；请检查原消息。', 'TRANS-AM 输出');
      } finally { if (generation === current) generation = null; }
      return;
    }
    if (wrapped) return;
    const text = raw.replace(/^```(?:json)?[ \t]*\r?\n/i, '').replace(/\r?\n```$/, '');
    const isEnvelope = text.startsWith('{') && /"transam_unicode"\s*:\s*1(?:\s*[,}])/.test(text);
    if (isEnvelope && !current.unicode) return;
    if (!isEnvelope && text.startsWith('{')) return;
    let envelope;
    let content;
    let partial = false;
    let layoutOnly = false;
    if (!isEnvelope) {
      content = normalizeStoryNewlines(last.mes);
      if (content === last.mes) return;
      layoutOnly = true;
    }
    try { if (isEnvelope) envelope = JSON.parse(text); } catch {
      content = recoverEnvelope(text);
      partial = content != null;
      if (!partial && !current.warned) {
        current.warned = true;
        toastr.warning('Unicode JSON已损坏，尚无可安全恢复的正文；原消息已保留。', 'TRANS-AM 输出');
      }
