 const injectionSnapshots=new WeakMap();
 function contentText(content){if(typeof content==='string')return content;if(Array.isArray(content))return content.filter(p=>p?.type==='text'&&typeof p.text==='string').map(p=>p.text).join('');return null;}
 function prefixContent(content,prefix,keepPilot=false){
