function saveSummaryForm(extraModels = null, silent = false) {
  let prevCount = 30;
  let autoByChat = {};
  let cachedModels = [];
  let connections = {};
  try {
    const prev = readSummarySettings();
    connections = { ...prev.connections };
    prevCount = prev.count;
    autoByChat = { ...prev.autoByChat };
    cachedModels = prev.cachedModels;
  } catch {}
  const rawCount = Number(summaryCount.value);
  const validCount = Number.isInteger(rawCount) && rawCount >= 2 && rawCount <= 100;
  if (!validCount && !silent) throw Error('每批楼数请输入 2～100 的整数。');
  const count = validCount ? rawCount : prevCount;
  if (Array.isArray(extraModels)) cachedModels = extraModels;
  const scope = summaryChatScope();
  if (scope && summaryAuto.checked) autoByChat[scope] = true;
  else if (scope) delete autoByChat[scope];
  const settings = {
    count,
    mode: summaryMode.value,
    apiurl: summaryMode.value === 'catiecli' ? summaryCatUrl : summaryUrl.value.trim(),
    model: summaryModel.value.trim(),
    key: summaryKey.value.trim(),
    cachedModels,
    connections,
    autoByChat,
  };
  connections[settings.mode === 'main' ? 'custom' : settings.mode] = { apiurl: settings.apiurl, model: settings.model, key: settings.key, cachedModels };
  if (!silent) summaryCustomApi(settings);
  host.localStorage.setItem(summarySettingsKey, JSON.stringify(settings));
  if (!silent) summaryStatus.textContent = '设置已保存。';
  return settings;
}

async function fetchSummaryModelsList() {
  const rawUrl = summaryMode.value === 'catiecli' ? summaryCatUrl : summaryUrl.value.trim();
  const rawKey = summaryKey.value.trim();
  if (!rawUrl) throw Error('请先填写 OpenAI 兼容 API 基础地址。');
  let parsedUrl;
  try { parsedUrl = new URL(rawUrl); } catch { throw Error('请填写有效的 HTTP 或 HTTPS API 基础地址。'); }
  if (!['http:', 'https:'].includes(parsedUrl.protocol) || parsedUrl.username || parsedUrl.password || parsedUrl.search || parsedUrl.hash) {
    throw Error('独立 API 地址须为 HTTP 或 HTTPS 基础地址。');
  }
  const base = parsedUrl.href.replace(/\/+$/, '').replace(/\/chat\/completions$/i, '').replace(/\/models$/i, '');
  const extractIds = payload => {
    const rawList = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload?.models) ? payload.models : Array.isArray(payload) ? payload : [];
    return [...new Set(
      rawList
        .map(item => typeof item === 'string' ? item : (item?.id || item?.name || ''))
        .map(s => String(s).replace(/^models\//i, '').trim())
        .filter(Boolean)
    )].sort((a, b) => a.localeCompare(b));
  };

  summaryFetchingModels = true;
  renderSummaryRunState();
  summaryStatus.textContent = '正在获取模型列表…';
  try {
    const endpoints = /\/v\d+[a-z0-9_-]*$/i.test(base) ? [base + '/models'] : [base + '/models', base + '/v1/models'];
    const headers = { Accept: 'application/json' };
    if (rawKey) headers.Authorization = 'Bearer ' + rawKey;
    let models = [];
    let lastErr = '';
    for (const ep of endpoints) {
      try {
        const res = await host.fetch(ep, { method: 'GET', headers });
        if (res?.ok) {
          const data = await res.json();
          models = extractIds(data);
          if (models.length) break;
        } else if (res) {
          lastErr = 'HTTP ' + res.status;
        }
      } catch (e) {
        lastErr = e?.message || String(e);
      }
    }
    if (!models.length) {
      const current = bigSummaryContext();
      const stHeaders = typeof current?.getRequestHeaders === 'function'
        ? current.getRequestHeaders()
        : { 'Content-Type': 'application/json' };
      const proxyRes = await host.fetch('/api/backends/chat-completions/status', {
        method: 'POST',
        headers: stHeaders,
        body: JSON.stringify({
          chat_completion_source: 'custom',
          custom_url: base,
          api_key_custom: rawKey,
          custom_include_headers: rawKey ? 'Authorization: Bearer ' + rawKey : '',
        }),
      });
      if (proxyRes?.ok) {
        const proxyData = await proxyRes.json();
        models = extractIds(proxyData?.data ?? proxyData);
      }
    }
    if (!models.length) {
      throw Error('未获取到可用模型列表' + (lastErr ? '（' + lastErr + '）' : '，请检查地址与密钥是否正确。'));
    }
    const currentModel = summaryModel.value.trim();
    const chosen = currentModel && models.includes(currentModel) ? currentModel : models[0];
    summaryModel.value = chosen;
    populateSummaryModelSelect(models, chosen);
    saveSummaryForm(models, true);
    summaryStatus.textContent = '已成功获取 ' + models.length + ' 个模型，当前已选：' + chosen;
  } finally {
    summaryFetchingModels = false;
    if (!quickDisposed) renderSummaryRunState();
  }
}

