function cancelAutoSummary() {
  // ta_issue42_summary_abort: only an auto summary that is actually running may be aborted here; never touch an idle or manual run.
  if (activeSummaryIsAuto && bigSummaryBusy && !bigSummaryAbort) {
    triggerBigSummaryAbort('自动总结已被新的生成或停止事件取消。');
  }
  summaryEpoch++;
  summaryTurn = null;
  if (summaryTimer != null) host.clearTimeout(summaryTimer);
  summaryTimer = null;
}

function onSummaryTurnStart(type, options, dryRun) {
  if (dryRun) return;
  if (bigSummaryBusy) return; // ta_issue39_summary_silent_gen: the summary's own silent generation must not cancel the summary.
  cancelAutoSummary();
  if (type !== 'normal') return;
  const current = bigSummaryContext();
  const scope = summaryChatScope(current);
  if (!scope || !Array.isArray(current?.chat)) return;
  summaryTurn = { scope, chat: current.chat, length: current.chat.length, epoch: summaryEpoch };
}

function onSummaryTurnEnd() {
  void refreshSummaryProgress();
  const turn = summaryTurn;
  summaryTurn = null;
  if (!turn) return;
  const afterReply = async attempt => {
    summaryTimer = null;
    const current = bigSummaryContext();
    if (quickDisposed || summaryEpoch !== turn.epoch || current?.chat !== turn.chat || summaryChatScope(current) !== turn.scope) return;
    if (bigSummaryBusy) {
      summaryTimer = host.setTimeout(() => void afterReply(attempt), 400);
      return;
    }
    if (continueHostBusy() || quickBusy || manualContinueState.active) {
      if (attempt < 8) summaryTimer = host.setTimeout(() => void afterReply(attempt + 1), 400);
      return;
    }
    const last = current.chat.at(-1);
    if (current.chat.length <= turn.length || last?.is_user !== false || last.is_system || !last.mes?.trim()) return;
    try {
      await syncUnresolvedItems(last.mes, turn, last);
      if (summaryEpoch !== turn.epoch || bigSummaryContext()?.chat !== turn.chat) return;
      const settings = readSummarySettings();
      if (settings.autoByChat[turn.scope] === true && bigSummaryTargets(current.chat, settings.count).length >= settings.count) {
        await runBigSummary(settings.count, summaryCustomApi(settings), { singleBatch: true, auto: true });
      }
    } catch (error) { summaryFailure(error); }
  };
  summaryTimer = host.setTimeout(() => void afterReply(0), 400);
}

function onSummaryChatChanged() {
  if (bigSummaryBusy) triggerBigSummaryAbort('聊天已切换，总结已停止。');
  cancelAutoSummary();
  branchIsolationPromise = null;
  branchIsolationChat = null;
  branchIsolationChatId = '';
  summaryStatus.textContent = '';
  void (async () => {
    try {
      await ensureSummaryBranchIsolation();
      void refreshSummaryProgress();
      if (consoleTab === 'summary') loadSummaryForm();
    } catch {}
  })();
}

