/* Standalone compatibility patch. No remote code, preset changes or model requests. */
(() => {
  'use strict';
  const host = window.parent;
  const ctx = () => host.SillyTavern?.getContext?.();
  if (typeof eventOn !== 'function' || typeof setChatMessages !== 'function' || !ctx()?.chat) {
    host.toastr?.error?.('需要酒馆助手消息接口，Unicode 修复脚本未启动。');
    return;
  }
  const slot = '__TA_UNWRAPPED_UNICODE_PATCH__';
  host[slot]?.dispose?.();
  function restore(text) {
    if (!/<(?:(?:ta|tw)_(?:zh|plan|source|record|status|choices|npc_inner)|bbs_start)\b/i.test(text)) return text;
    // Protect executable/data blocks, inline code, markup attributes and paths.
    const protectedParts = /(<(script|style|pre|code|iframe|UpdateVariable|JSONPatch|ta_hub|tw_hub|div|details|svg)\b[^>]*>[\s\S]*?(?:<\/\2\s*>|$)|```[\s\S]*?(?:```|$)|~~~[\s\S]*?(?:~~~|$)|`[^`\r\n]*(?:`|$)|<[^>]*>|[A-Za-z]:\\[^\s<>"'`]+|\\\\[A-Za-z0-9_.-]+\\[^\s<>"'`]+)/gi;
    // Replace only text outside protected spans; never evaluate generated code.
    let result = '', cursor = 0;
    const decode = part => part.replace(/\\\\|\\u[dD][89aAbB][0-9a-f]{2}\\u[dD][c-fC-F][0-9a-f]{2}|\\u[0-9a-f]{4}/gi, token => {
      if (token === '\\\\') return token;
      const first = parseInt(token.slice(2, 6), 16);
      if (first < 128 || (token.length === 6 && first >= 0xd800 && first <= 0xdfff)) return token;
      return String.fromCharCode(first) + (token.length === 12 ? String.fromCharCode(parseInt(token.slice(8), 16)) : '');
    });
    for (const match of text.matchAll(protectedParts)) {
      result += decode(text.slice(cursor, match.index)) + match[0];
      cursor = match.index + match[0].length;
    }
    return result + decode(text.slice(cursor));
  }
  let busy = false;
  async function repair(id, manual = false) {
    if (busy) return;
    const chat = ctx()?.chat;
    if (!chat) return;
    if (manual) id = chat.findLastIndex(m => !m.is_user && !m.is_system);
    if (!Number.isInteger(id) || id < 0 || (!manual && id !== chat.length - 1)) return;
    const message = chat[id];
    if (!message || message.is_user || message.is_system || typeof message.mes !== 'string') return;
    const raw = message.mes;
    // JSON envelopes belong to the existing Unicode transport script.
    if (/^\s*(?:\{|```)/.test(raw)) return;
    const decoded = restore(raw);
    if (decoded === raw) { if (manual) host.toastr?.info?.('最近助手消息没有可安全还原的裸 Unicode 转义。'); return; }
    busy = true;
    try {
      await setChatMessages([{ message_id: id, message: decoded, extra: { ...message.extra, transam_bare_unicode_recovery: { source: raw, status: 'recovered' } } }]);
      if (manual) host.toastr?.success?.('已还原最近助手消息，原文已保存在该消息附加数据中。');
    } catch (error) {
      host.toastr?.error?.('Unicode 回写失败，请保留原消息。');
      console.error('[TRANS-AM Unicode patch]', error?.name ?? 'Error');
    } finally { busy = false; }
  }
  const listeners = [eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, id => repair(id))];
  if (typeof getButtonEvent === 'function') listeners.push(eventOn(getButtonEvent('修复最近助手消息'), () => repair(null, true)));
  const dispose = () => { listeners.forEach(listener => listener?.stop?.()); if (host[slot]?.dispose === dispose) delete host[slot]; };
  host[slot] = { dispose };
  window.addEventListener('pagehide', dispose, { once: true });
})();
